#include <cmath>
#include <algorithm>

template <typename T>
struct Vector3 {
    T x, y, z;
    Vector3() : x(0), y(0), z(0) {}
    Vector3(T x, T y, T z) : x(x), y(y), z(z) {}
    T LengthSquared() const { return x * x + y * y + z * z; }
    T Length() const { return std::sqrt(LengthSquared()); }
};

template <typename T>
Vector3<T> Cross(const Vector3<T> &a, const Vector3<T> &b) {
    return Vector3<T>(
        a.y * b.z - a.z * b.y,
        a.z * b.x - a.x * b.z,
        a.x * b.y - a.y * b.x
    );
}

template <typename T>
Vector3<T> Normalize(const Vector3<T> &v) {
    T len = v.Length();
    return len == 0 ? Vector3<T>(0, 0, 0) : Vector3<T>(v.x / len, v.y / len, v.z / len);
}

template <typename T>
inline void CoordinateSystem(const Vector3<T> &v1, Vector3<T> *v2, Vector3<T> *v3) {
    if (std::abs(v1.x) > std::abs(v1.y)) {
        *v2 = Normalize(Cross(v1, Vector3<T>(0, 1, 0)));
    } else {
        *v2 = Normalize(Cross(v1, Vector3<T>(1, 0, 0)));
    }
    *v3 = Cross(v1, *v2);
}

